import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.CHi0mXvr.js";import"./chunks/assets.tD9y118P.js";var i=JSON.parse(`{"title":"プロジェクト","description":"AIベースのテスト自動化でQA時間を80%削減します。コードなしのテスト作成、自然言語によるシナリオ作成、多様なプラットフォームのサポートにより、QAの新しい基準を提示します。","frontmatter":{"title":"プロジェクト","description":"AIベースのテスト自動化でQA時間を80%削減します。コードなしのテスト作成、自然言語によるシナリオ作成、多様なプラットフォームのサポートにより、QAの新しい基準を提示します。","head":[["meta",{"name":"keywords","content":"テスト自動化, テスティング生成型AI, Playwright, Selenium, リアルタイム品質フィードバック, 無停止テスト, AIベーステスト自動化, 継続的テスト(Continuous Testing), QAOps, TestOps, コードレス(Codeless), ローコード(Low-Code), 自己修復テスト(Self-healing), AIテスト自動化, コードレス自動化, QA自動化, ソフトウェアテスト, テストシナリオ生成, コードレステスト, 自然言語テスト, テスト自動化ツール, テスト自動化プラットフォーム, テスト効率化, Playwright, Selenium, QAOps, TestOps, シフトレフト(Shift-Left)テスト, シフトライト(Shift-Right)テスト"}],["meta",{"property":"og:title","content":"AIテスト自動化 | SyncETA"}],["meta",{"property":"og:description","content":"AIベースのテスト自動化でQA時間を80%削減します。コードなしのテスト作成、自然言語によるシナリオ作成、多様なプラットフォームのサポートにより、QAの新しい基準を提示します。"}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/synceta/"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/synceta/project.html"}]],"sort":400},"headers":[],"relativePath":"ja/synceta/project.md","filePath":"ja/synceta/project.md","lastUpdated":1786532854000}`),a={name:`ja/synceta/project.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="プロジェクト" tabindex="-1">プロジェクト <a class="header-anchor" href="#プロジェクト" aria-label="Permalink to “プロジェクト”">​</a></h1><p>SyncETAを通じて多様な <strong><em>「単体テスト」</em></strong> と <strong><em>「統合テスト」</em></strong> を管理することになります。</p><p><strong><em>「プロジェクト」</em></strong> は複数のテストを管理する最も大きな分類単位です。<br> ユーザーはプロジェクトに <strong><em>「メンバー」</em></strong> として登録され、SyncETAソリューションを使用することになります。<br> プロジェクトにメンバーを招待し、メンバーごとに作業権限を付与する方法を説明します。</p><h2 id="プロジェクト作成" tabindex="-1">プロジェクト作成 <a class="header-anchor" href="#プロジェクト作成" aria-label="Permalink to “プロジェクト作成”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>以下の3つの場合においてプロジェクトを作成する方法</p><ol><li>所属しているプロジェクトがない場合</li><li>所属しているプロジェクトが存在する場合</li><li>他のプロジェクトで作業中の場合</li></ol></div><h4 id="_1-所属しているプロジェクトがない場合にプロジェクトを作成する方法。" tabindex="-1">1. 所属しているプロジェクトがない場合にプロジェクトを作成する方法。 <a class="header-anchor" href="#_1-所属しているプロジェクトがない場合にプロジェクトを作成する方法。" aria-label="Permalink to “1. 所属しているプロジェクトがない場合にプロジェクトを作成する方法。”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>所属しているプロジェクトがない場合は、画面中央の <strong><em>「新しいプロジェクト」</em></strong> ボタンをクリックします。</p></div><p><img src="/docs/assets/project_none.Bf5vSZJG.png" alt="プロジェクトなし" loading="lazy"></p><h4 id="_2-所属しているプロジェクトが存在する場合にプロジェクトを追加する方法。" tabindex="-1">2. 所属しているプロジェクトが存在する場合にプロジェクトを追加する方法。 <a class="header-anchor" href="#_2-所属しているプロジェクトが存在する場合にプロジェクトを追加する方法。" aria-label="Permalink to “2. 所属しているプロジェクトが存在する場合にプロジェクトを追加する方法。”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>所属しているプロジェクトがあり、プロジェクトを追加したい場合は、プロジェクトリストの左上にある <strong><em>「新しいプロジェクト」</em></strong> ボタンをクリックします。</p></div><p><img src="/docs/assets/project_list.CN-f9Nmf.png" alt="プロジェクトリストから作成する" loading="lazy"></p><h4 id="_3-他のプロジェクトで作業中にプロジェクトを追加する方法。" tabindex="-1">3. 他のプロジェクトで作業中にプロジェクトを追加する方法。 <a class="header-anchor" href="#_3-他のプロジェクトで作業中にプロジェクトを追加する方法。" aria-label="Permalink to “3. 他のプロジェクトで作業中にプロジェクトを追加する方法。”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>画面左上のプロジェクトツールバーの <strong><em>「新しいプロジェクト」</em></strong> ボタンをクリックします。</p></div><p><img src="/docs/assets/create_project_in_dashboard.CbXntOhP.png" alt="プロジェクトダッシュボードから作成する" loading="lazy"></p><h4 id="_4-プロジェクト作成" tabindex="-1">4. プロジェクト作成 <a class="header-anchor" href="#_4-プロジェクト作成" aria-label="Permalink to “4. プロジェクト作成”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>上記の3つの方法でプロジェクト作成画面に移動できます。<br> プロジェクトのプロフィール画像、プロジェクト名、プロジェクトの説明を入力してプロジェクトを作成します。</p></div><p><img src="/docs/assets/create_project.DRRa7-ti.png" alt="プロジェクト作成フォーム" loading="lazy"></p><h2 id="プロジェクトリスト" tabindex="-1">プロジェクトリスト <a class="header-anchor" href="#プロジェクトリスト" aria-label="Permalink to “プロジェクトリスト”">​</a></h2><h4 id="_1-プロジェクトリストへ移動" tabindex="-1">1. プロジェクトリストへ移動 <a class="header-anchor" href="#_1-プロジェクトリストへ移動" aria-label="Permalink to “1. プロジェクトリストへ移動”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>右上の <strong><em>「プロジェクトを閉じる」</em></strong> ボタンをクリックして、現在所属しているプロジェクトリストを確認できます。</p></div><p><img src="/docs/assets/goto_project_list.BwA4HDXL.png" alt="プロジェクトリストへ移動" loading="lazy"></p><h4 id="_2-プロジェクトリスト照会" tabindex="-1">2. プロジェクトリスト照会 <a class="header-anchor" href="#_2-プロジェクトリスト照会" aria-label="Permalink to “2. プロジェクトリスト照会”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>自分が所属しているプロジェクトリストを確認できます。</p></div><p><img src="/docs/assets/project_list_org.C08gK4JK.png" alt="プロジェクトリスト" loading="lazy"></p><h2 id="役割-権限設定" tabindex="-1">役割 / 権限設定 <a class="header-anchor" href="#役割-権限設定" aria-label="Permalink to “役割 / 権限設定”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>プロジェクトごとに役割(role)を作成し、権限を付与することができます。</p></div><h4 id="_1-役割作成" tabindex="-1">1. 役割作成 <a class="header-anchor" href="#_1-役割作成" aria-label="Permalink to “1. 役割作成”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>役割作成画面へ移動</p></div><p><img src="/docs/assets/new_role.DNJf18SI.png" alt="役割作成へ移動" loading="lazy"></p><h4 id="_2-権限設定" tabindex="-1">2. 権限設定 <a class="header-anchor" href="#_2-権限設定" aria-label="Permalink to “2. 権限設定”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>役割に付与する権限を設定します。</p></div><p><img src="/docs/assets/role_setting.B_EeIWEH.png" alt="役割設定" loading="lazy"></p><h2 id="メンバー管理" tabindex="-1">メンバー管理 <a class="header-anchor" href="#メンバー管理" aria-label="Permalink to “メンバー管理”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>プロジェクトにメンバーを招待し、作業権限を付与します。</p></div><h4 id="_1-メンバー招待" tabindex="-1">1. メンバー招待 <a class="header-anchor" href="#_1-メンバー招待" aria-label="Permalink to “1. メンバー招待”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>メンバー招待画面へ移動</p></div><p><img src="/docs/assets/new_member.CsjjO5hi.png" alt="メンバー招待画面へ移動" loading="lazy"></p><h4 id="_2-メンバー招待" tabindex="-1">2. メンバー招待 <a class="header-anchor" href="#_2-メンバー招待" aria-label="Permalink to “2. メンバー招待”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>プロジェクトに招待するメンバーを選択します。</p></div><p><img src="/docs/assets/vite_member.BEx5eaHn.png" alt="メンバー招待" loading="lazy"></p><h4 id="_3-権限付与" tabindex="-1">3. 権限付与 <a class="header-anchor" href="#_3-権限付与" aria-label="Permalink to “3. 権限付与”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>招待したメンバーに権限を付与します。</p><ul><li>該当の権限はプロジェクト内でのみ有効です。<br> ex) Aプロジェクトで管理者権限を持つユーザーが、Bプロジェクトではテスター(例)権限である可能性があります。</li></ul></div><p><img src="/docs/assets/set_role_to_member.B5eGbdu6.png" alt="メンバーへの役割付与" loading="lazy"></p>`,43)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};